input.command:
grep -n "\-\-cut\|--base" docs/replay-spec.md docs/sandbox-spec.md | cut -c1-240 | head -12; cd investigations/goal-prompt && hyp events --json 2>/dev/null | python3 -I -c "
import json,sys
d=json.load(sys.stdin)
ev=d.get('events',d) if isinstance(d,dict) else d
n={}
for e in ev:
    e=e.get('event',e)
    t=e.get('type');a=e.get('actor');i=e.get('id')
    if t=='result.record':
        n.setdefault(a,[]).append(e.get('result_id') or e.get('node') or i)
for a,v in n.items(): print(a,len(v),v)
" | head -20

